contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller) public payable {
        require(caller != address(0), "caller must be nonzero");
        require(caller != address(this), "caller must not be this test contract");
        require(c.owner() == address(this), "test contract must currently be owner");

        uint256 beforeSupply = c.totalSupply();
        uint256 beforeCallerBal = c.balanceOf(caller);

        bool reverted;
        try c.owned() {
            reverted = false;
        } catch {
            reverted = true;
        }

        address afterOwner = c.owner();
        uint256 afterSupply = c.totalSupply();
        uint256 afterCallerBal = c.balanceOf(caller);

        assert(!reverted);
        assert(afterOwner == address(this));
        assert(afterSupply == beforeSupply);
        assert(afterCallerBal == beforeCallerBal);
    }

    receive() external payable {}
}

