contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public {
        uint256 balanceBefore = c.balanceOf(address(this));
        uint256 supplyBefore = c.totalSupply();

        bool reverted;
        try c.burn(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (reverted) {
            assert(balanceBefore < amount);
        } else {
            assert(balanceBefore >= amount);
            assert(c.balanceOf(address(this)) == balanceBefore - amount);
            assert(c.totalSupply() == supplyBefore - amount);
        }
    }
}
